    const startTime = Date.now();

    function update() {
        const elapsed = Date.now() - startTime;
        const progress = Math.min(elapsed / duration, 1);

        // Ease in-out
        const easedProgress = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;

        if (open) {
            leftDoor.position.x = startLeftX + (originalLeftX - startLeftX) * easedProgress;
            rightDoor.position.x = startRightX + (originalRightX - startRightX) * easedProgress;
        } else {
            leftDoor.position.x = startLeftX + (originalLeftX - startLeftX) * easedProgress;
            rightDoor.position.x = startRightX + (originalRightX - startRightX) * easedProgress;
        }

        if (progress < 1) {
            requestAnimationFrame(update);
        } else {
            doorAnimationActive = false;
            // Snap to final position
            if (open) {
                leftDoor.position.x = originalLeftX;
                rightDoor.position.x = originalRightX;
            } else {
                leftDoor.position.x = 0.1;
                rightDoor.position.x = -0.1;
            }
            if (done) done();
        }
    }

    requestAnimationFrame(update);
}

