                                        // Close doors
                                        animateDoors(false, () => {
                                            // Update floor tracking
                                            emptyFloor = sourceFloor;
                                            person.userData.currentFloor = destFloor;

                                            // Schedule next trip
                                            setTimeout(completeTripSequence, 1000);
                                        });
                                    });
                                });
                            });
                        });
                    });
                });
            });
        });
    });
}

