function animateDoors(open, done) {
    if (doorAnimationActive) {
        setTimeout(() => {
            animateDoors(open, done);
        }, 100);
        return;
    }

    doorAnimationActive = true;
    const leftDoor = elevatorCar.leftDoor;
    const rightDoor = elevatorCar.rightDoor;
    const originalLeftX = open ? -(SHAFT_WIDTH - 0.4) / 2 + 0.1 : -(0.1);
    const originalRightX = open ? (SHAFT_WIDTH - 0.4) / 2 - 0.1 : 0.1;

    // Get current positions if animating from closed to open or vice versa
    let startLeftX, startRightX;
    if (open) {
        startLeftX = leftDoor.position.x;
        startRightX = rightDoor.position.x;
    } else {
        startLeftX = leftDoor.position.x;
        startRightX = rightDoor.position.x;
    }

    const duration = 1000 / speedMultiplier;
    const startTime = Date.now();

    function update() {
        const elapsed = Date.now() - startTime;
        const progress = Math.min(elapsed / duration, 1);

        // Ease in-out
        const easedProgress = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;

        if (open) {
            leftDoor.position.x = startLeftX + (originalLeftX - startLeftX) * easedProgress;
            rightDoor.position.x = startRightX + (originalRightX - startRightX) * easedProgress;
        } else {
            leftDoor.position.x = startLeftX + (originalLeftX - startLeftX) * easedProgress;
            rightDoor.position.x = startRightX + (originalRightX - startRightX) * easedProgress;
        }

        if (progress < 1) {
            requestAnimationFrame(update);
        } else {
            doorAnimationActive = false;
            // Snap to final position
            if (open) {
                leftDoor.position.x = originalLeftX;
                rightDoor.position.x = originalRightX;
            } else {
                leftDoor.position.x = 0.1;
                rightDoor.position.x = -0.1;
            }
            if (done) done();
        }
    }

    requestAnimationFrame(update);
}

edits.newText:
function animateDoors(open, done) {
    if (doorAnimationActive) {
        setTimeout(() => {
            animateDoors(open, done);
        }, 100);
        return;
    }

    doorAnimationActive = true;
    const leftDoor = elevatorCar.leftDoor;
    const rightDoor = elevatorCar.rightDoor;

    // Define target positions based on open/closed state
    let targetLeftX, targetRightX;
    if (open) {
        // Open: doors slide to sides
        targetLeftX = -(SHAFT_WIDTH - 0.4) / 2 + 0.1;
        targetRightX = (SHAFT_WIDTH - 0.4) / 2 - 0.1;
    } else {
        // Closed: doors meet in center
        targetLeftX = -0.1;
        targetRightX = 0.1;
    }

    const startLeftX = leftDoor.position.x;
    const startRightX = rightDoor.position.x;

    const duration = 1000 / speedMultiplier;
    const startTime = Date.now();

    function update() {
        const elapsed = Date.now() - startTime;
        const progress = Math.min(elapsed / duration, 1);

        // Ease in-out
        const easedProgress = progress < 0.5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2;

        leftDoor.position.x = startLeftX + (targetLeftX - startLeftX) * easedProgress;
        rightDoor.position.x = startRightX + (targetRightX - startRightX) * easedProgress;

        if (progress < 1) {
            requestAnimationFrame(update);
        } else {
            doorAnimationActive = false;
            // Snap to final position
            leftDoor.position.x = targetLeftX;
            rightDoor.position.x = targetRightX;
            if (done) done();
        }
    }

    requestAnimationFrame(update);
}

